function [pdf,cdf] = spa_uni_hp(Kd,shat,xbar,order)
%SPA_UNI_HP Variable-precision version of spa_uni (Symbolic Math Toolbox): Daniels density and
%   Hauschildt-Robinson distribution function P[X <= xbar] of orders 1..order, computed with the
%   current digits().  Kd (vpa) with Kd(k+1) = K^{(k)}(shat), k = 0,...,2*order+1.
%   The integrals I_m are generated by the forward recursion (35), which loses about
%   log10(u^(2m+1)/m!) digits at index m, u = shat*sqrt(K''); digits() must exceed that loss
%   (for m <= 33 and |u| <= 10 about 20 digits) by the accuracy wanted.
%   Raymond Kan (raymond.kan@rotman.utoronto.ca), 2026. Programs accompanying Broda and Kan,
%   "Uniform saddlepoint expansions for multivariate tail probabilities"; free to use and modify with a citation of the paper.
p = 2*order-1;
N = p+2;
Kd = vpa(Kd(:)); shat = vpa(shat); xbar = vpa(xbar);
K2 = Kd(3);
k = (3:N)';
theta = Kd(k+1)./(factorial(sym(k)).*K2.^(k/2)); % theta(k-2) = theta_k (exact factorials)
J = N-2;
d = vpa(zeros(J,J));                              % d(r,j) = [s^j] Theta(s)^r/r!
d(1,1:J) = theta(1:J).';
for r = 2:J
   for j = r:J
      d(r,j) = theta(1:j-r+1).'*d(r-1,j-1:-1:r-1).'/r;
   end
end
h = cumprod(sym([1; -(1:2:4*J-1)']));             % h_i = (-2)^i (1/2)_i, exact
f0 = exp(Kd(1)-shat*xbar)/sqrt(2*vpa(pi)*K2);
pdf = vpa(zeros(order,1));
s = vpa(1); pdf(1) = f0;
for M = 2:order
   s = s+sum(d(1:2*(M-1),2*(M-1)).*h(M-1+(1:2*(M-1))'+1));
   pdf(M) = f0*s;
end
u = shat*sqrt(K2);
E = exp(Kd(1)-shat*xbar+u^2/2);
I = vpa(zeros(3*p+1,1));
phiu = exp(-u^2/2)/sqrt(2*vpa(pi));
neg = isAlways(shat < 0);                       % sign test in symbolic arithmetic
if ~neg
   I(1) = erfc(u/sqrt(vpa(2)))/2;                % Phi(-u)
else
   I(1) = -erfc(-u/sqrt(vpa(2)))/2;              % -Phi(u)
end
for i = 0:3*p-1
   if rem(i,2) == 0
      I(i+2) = h(i/2+1)*phiu-u*I(i+1);
   else
      I(i+2) = -u*I(i+1);
   end
end
cdf = vpa(zeros(order,1));
s = I(1); m = 0;
for M = 1:order
   while m < 2*M-1
      m = m+1;
      for r = 1:m
         s = s+d(r,m)*I(m+2*r+1);
      end
   end
   if ~neg
      cdf(M) = 1-E*s;
   else
      cdf(M) = -E*s;
   end
end
end
